import json


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def read_json(text):
    if not isinstance(text, str):
        raise ValueError('text required')
    try:
        return json.loads(text, object_pairs_hook=unique_object)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc


def string(value):
    return isinstance(value, str) and bool(value)


def integer(value, minimum):
    return isinstance(value, int) and value >= minimum


def parse_event(line):
    event = read_json(line)
    if not isinstance(event, dict) or not string(event.get('id')):
        raise ValueError('event object and id required')
    op = event.get('op')
    fields = {'restock': {'id', 'op', 'sku', 'qty'},
              'reserve': {'id', 'op', 'request', 'lines'},
              'cancel': {'id', 'op', 'request'}}
    if not isinstance(op, str) or op not in fields or set(event) != fields[op]:
        raise ValueError('operation or fields')
    if op == 'restock':
        if not string(event['sku']) or not integer(event['qty'], 1):
            raise ValueError('restock fields')
    elif not string(event['request']):
        raise ValueError('request')
    if op == 'reserve':
        if not isinstance(event['lines'], list):
            raise ValueError('lines')
        quantities = {}
        for pair in event['lines']:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ValueError('pair')
            sku, qty = pair
            if not string(sku) or not integer(qty, 1):
                raise ValueError('quantity')
            quantities[sku] = qty
        event['lines'] = [[sku, qty] for sku, qty in sorted(quantities.items())]
    return event
